<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import UiverseVideoLink from './UiverseVideoLink.vue'
const props=defineProps({works:{type:Array,required:true}})
const paused=ref(false),showcase=ref(null),inView=ref(false),selectionPulse=ref(0)
let rotationTimer,observer
onMounted(()=>{observer=new IntersectionObserver(([entry])=>{inView.value=entry.isIntersecting},{threshold:.25});if(showcase.value)observer.observe(showcase.value);scheduleRotation()})
onUnmounted(()=>{clearTimeout(rotationTimer);observer?.disconnect()})
function scheduleRotation(){clearTimeout(rotationTimer);rotationTimer=setTimeout(()=>{if(!paused.value&&!document.hidden&&inView.value&&!dialog.value?.open)choose((active.value+1)%props.works.length);else scheduleRotation()},6000)}
const previewSource=item=>source(item.images[0])
const active=ref(0),angle=ref(0),dialog=ref(null),direction=ref(1)
const work=computed(()=>props.works[active.value])
const image=computed(()=>work.value.images[angle.value])
const source=img=>typeof img==='string'?img:img?.src
const waterTarget=ref(-1),waterPulse=ref(0)
function pulseWater(i){waterTarget.value=i;waterPulse.value++}
function waterOrigin(event,i){const r=event.currentTarget.querySelector('.miniature-preview').getBoundingClientRect();event.currentTarget.style.setProperty('--water-x',`${Math.max(0,Math.min(r.width,event.clientX-r.left))}px`);event.currentTarget.style.setProperty('--water-y',`${Math.max(0,Math.min(r.height,event.clientY-r.top))}px`);pulseWater(i)}
const choose=i=>{active.value=i;angle.value=0;selectionPulse.value++;pulseWater(i);scheduleRotation()}

defineExpose({selectWork(title){const i=props.works.findIndex(work=>work.title===title);if(i>=0)choose(i)}})
const label=(img,i)=>typeof img==='string'?`画面 ${i+1}`:img.label||`画面 ${i+1}`

const setAngle=i=>{if(i===angle.value)return;direction.value=i>angle.value?1:-1;angle.value=i}
const change=step=>{const n=work.value.images.length;if(n){direction.value=step>0?1:-1;angle.value=(angle.value+step+n)%n}}
</script>
<template>
  <svg width="0" height="0" aria-hidden="true" class="water-filter-defs"><defs><filter id="landscape-liquid-waves" x="-30%" y="-30%" width="160%" height="160%"><feTurbulence type="fractalNoise" baseFrequency=".018 .045" numOctaves="2" seed="7" result="noise"><animate attributeName="baseFrequency" values=".018 .045;.025 .032;.018 .045" dur="5s" repeatCount="indefinite"/></feTurbulence><feDisplacementMap in="SourceGraphic" in2="noise" scale="30" xChannelSelector="R" yChannelSelector="G"/></filter></defs></svg>
  <div ref="showcase" class="miniature-showcase" :class="{'single-showcase':works.length===1}">
    <div class="miniature-main" @pointerenter="paused=true" @pointerleave="paused=false;scheduleRotation()" @focusin="paused=true" @focusout="paused=false;scheduleRotation()">
      <Transition name="scene-fade" mode="out-in"><div :key="active" class="miniature-scene" :class="{'has-image':image}">
        <div v-if="image" class="landscape-accordion" :style="{'--panels':work.images.length}" aria-label="景观画廊，悬停展开画面">
          <div v-for="(img,i) in work.images" :key="source(img)" class="landscape-panel" :class="{'is-open':angle===i}" @pointerenter="$event.pointerType==='mouse' && setAngle(i)">
            <button class="landscape-select" :aria-expanded="angle===i" :aria-label="`展开${label(img,i)}`" @click="setAngle(i)" @keydown.left.prevent="change(-1)" @keydown.right.prevent="change(1)"><img :src="source(img)" :alt="`${work.title} · ${label(img,i)}`" draggable="false"><span class="landscape-panel-caption"><b>{{String(i+1).padStart(2,'0')}}</b><span>{{label(img,i)}}</span></span></button>
            <button v-if="angle===i" class="landscape-enlarge" @click="dialog.showModal()" :aria-label="`放大${label(img,i)}`">查看大图 ＋</button>
          </div>
        </div>
        <div v-else class="miniature-empty"><span class="miniature-index">{{String(active+1).padStart(2,'0')}}</span><div><small>MINIATURE LANDSCAPES</small><h3>{{work.title}}</h3><p>展示图片待补充</p></div></div>
      </div></Transition>
      <div v-if="work.images.length>1" class="accordion-status"><span>{{String(angle+1).padStart(2,'0')}} / {{String(work.images.length).padStart(2,'0')}} <b>{{label(image,angle)}}</b></span><small>悬停展开 · 查看不同光影与细节</small></div>
      <div class="miniature-info"><div><h3>{{work.title}}</h3><p>{{work.description}}</p><div v-if="works.length>1 || work.displayUrl" class="scene-external"><template v-if="work.displayUrl"><UiverseVideoLink :href="work.displayUrl" label="查看交互效果" /></template><span v-else>展示链接待补充 <span aria-hidden="true">↗</span></span></div></div><span v-if="works.length>1" class="miniature-medium">Three.js<br>微缩景观</span></div>

    </div>
    <div v-if="works.length>1" class="miniature-picker"><div class="miniature-picker-heading"><span>THE COLLECTION</span><small>选择一个小世界 ↓</small></div><div class="miniature-previews"><button v-for="(item,i) in works" :key="i" :aria-pressed="active===i" @pointerenter="waterOrigin($event,i)" @pointerdown="waterOrigin($event,i)" @click="choose(i)"><div class="miniature-preview" :class="{'preview-chosen':active===i}"><Transition name="preview-dissolve"><img v-if="item.images.length" :key="previewSource(item,i)" :src="previewSource(item,i)" :alt="item.title" loading="lazy"></Transition><span v-if="!item.images.length" class="miniature-preview-empty"><b>{{String(i+1).padStart(2,'0')}}</b><small>图片待补充</small></span><span v-if="waterTarget===i" :key="waterPulse" class="preview-water" aria-hidden="true"><i class="water-fog"></i><i class="water-ring ring-one"></i><i class="water-ring ring-two"></i></span></div><span class="miniature-preview-name">{{item.title}}<small v-if="item.pending">待补充</small></span></button></div></div>
    <dialog ref="dialog" class="gallery-dialog" @click="($event.target===dialog)&&dialog.close()" @keydown.left.prevent="change(-1)" @keydown.right.prevent="change(1)"><div class="gallery-dialog-head"><span>{{work.title}}</span><button @click="dialog.close()">关闭 ×</button></div><div class="gallery-dialog-inner"><img v-if="image" :src="source(image)" :alt="work.title"></div></dialog>
  </div>
</template>
