elect{min-height:0;height:40px;transition:height .5s}.landscape-panel.is-open{flex:none}.landscape-panel:not(.is-open) img{object-position:center 50%}.landscape-panel-caption{flex-direction:row;justify-content:flex-start;gap:18px;padding:0 14px;background:#17102044}.landscape-panel-caption>span{writing-mode:horizontal-tb;letter-spacing:1px}.accordion-status{align-items:start}.accordion-status small{max-width:115px;text-align:right}.landscape-enlarge{font-size:10px;padding:6px 10px;bottom:8px;right:8px}}@media(prefers-reduced-motion:reduce){.landscape-panel,.landscape-select,.landscape-select img{transition:none}}

